{
  "summary": "In November 2025 the orders database ran out of usable connection slots, causing 53300 errors and ORD-5003 responses from orders‑api.",
  "likely_cause": "A batch job leaked ~222 idle sessions, filling the 297 usable slots and exhausting the pool.",
  "confidence": "high",
  "claims": [
    {
      "text": "The incident was caused by a leak of idle sessions from a batch job that filled all usable slots.",
      "evidence_ids": ["INC-0103#1"],
      "quote": "The rest of the arithmetic is the leak: 222 idle sessions plus those 75 come to 297"
    },
    {
      "text": "When the slots were exhausted, new connections were refused with SQLSTATE 53300 and orders‑api returned ORD-5003.",
      "evidence_ids": ["INC-0103#0", "RB-012#1"],
      "quote": "new connection attempt was refused at login with `53300`... orders‑api ... answered with `ORD-5003`"
    }
  ],
  "next_checks": [
    "Run the query from RB-012#5 to count current client backend sessions per role.",
    "Identify the batch job pods in the commerce namespace and check their connection handling.",
    "Verify that pool sizes for orders‑api pods match the expected 75 connections.",
    "Confirm that no other services are unexpectedly consuming slots."
  ]
}
